// crAuth GATE — generated into every client webhook by Tools/n8n/apply-auth-gate.py from
// Tools/n8n/auth/gate.js (+ token.js). Edit the sources, re-run the migration; never the copies.
//
// Verifies the Bearer capability token WITHOUT a database round-trip (HMAC, see token.js), then
// checks that every id the request names is owned by the token's install:
//   RULE.profiles  — body fields whose value(s) must be ⊆ claims.p   (sentinels ''/'-1' pass)
//   RULE.workflows — body fields whose value(s) must be ⊆ claims.w   (sentinels ''/'-1' pass)
//   RULE.appUser   — body fields that must EQUAL claims.u; a token WITHOUT a billing identity (u = null: the
//                    id is held by another install or was not bindable) can name none (R2, 2026-09-27)
//   RULE.appUserRequired — appUser fields that may not be empty/sentinel in session mode (Create WA/TG: an
//                    empty AppUserID skipped the channel count and let the dialog quota fail open)
//   RULE.legacy    — true: a request WITHOUT a token is admitted in `legacy` mode while
//                    CR_AUTH_COMPAT_UNTIL lies in the future (old clients); false: 401
// Output: the webhook item re-emitted — json AND binary: a Code node drops whatever it does not return,
// and a multipart upload's parts (Unity WWWForm files even its text fields there) live in `binary`
// (R3, 2026-09-27) — with `crAuth` = { ok, mode, reason, installId, appUserId, profiles, workflows,
// claimPending } so downstream nodes can read the verified identity. The gate sees `body` only, so
// ids that arrive as multipart parts are checked by the workflow after it decodes them.
// CRAUTH-TOKEN-BEGIN
const crAuth = (() => {
  const crypto = require('crypto');
  const b64u = (buf) => Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const unb64u = (s) => Buffer.from(String(s).replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((String(s).length + 3) % 4), 'base64');
  const isIdList = (a) => Array.isArray(a) && a.every((x) => typeof x === 'string' && x.length > 0 && x.length <= 128);
  function sign(payload, secret) {
    if (!secret) throw new Error('crAuth: no signing secret');
    const p = b64u(JSON.stringify(payload));
    const sig = crypto.createHmac('sha256', secret).update('v1.' + p).digest();
    return 'v1.' + p + '.' + b64u(sig);
  }
  function verify(token, secrets, nowSec) {
    if (typeof token !== 'string' || !token) return { ok: false, reason: 'missing' };
    const parts = token.split('.');
    if (parts.length !== 3 || parts[0] !== 'v1' || !parts[1] || !parts[2]) return { ok: false, reason: 'malformed' };
    const given = unb64u(parts[2]);
    let good = false;
    for (const sec of (secrets || []).filter(Boolean)) {
      const exp = crypto.createHmac('sha256', sec).update(parts[0] + '.' + parts[1]).digest();
      if (exp.length === given.length && crypto.timingSafeEqual(exp, given)) { good = true; break; }
    }
    if (!good) return { ok: false, reason: 'bad_signature' };
    let c;
    try { c = JSON.parse(unb64u(parts[1]).toString('utf8')); } catch (e) { return { ok: false, reason: 'malformed' }; }
    if (!c || typeof c !== 'object' || typeof c.i !== 'string' || !c.i || !isIdList(c.p) || !isIdList(c.w)) return { ok: false, reason: 'malformed' };
    if (typeof c.e !== 'number' || !(c.e > nowSec)) return { ok: false, reason: 'expired' };
    if (c.c !== undefined && !isIdList(c.c)) return { ok: false, reason: 'malformed' };
    return { ok: true, claims: { i: c.i, u: (typeof c.u === 'string' && c.u) ? c.u : null, p: c.p, w: c.w, c: c.c || [], e: c.e, n: (typeof c.n === 'number') ? c.n : 1 } };
  }
  function sha256Hex(s) { return crypto.createHash('sha256').update(String(s)).digest('hex'); }
  function randomSecret(bytes) { return b64u(crypto.randomBytes(bytes || 32)); }
  function bearer(headers) {
    const h = headers || {};
    const a = String(h.authorization || h.Authorization || '');
    return a.startsWith('Bearer ') ? a.slice(7).trim() : '';
  }
  return { sign, verify, sha256Hex, randomSecret, bearer, b64u, unb64u };
})();
// CRAUTH-TOKEN-END
const RULE = {"profiles": ["profileId"], "workflows": ["workflowId"], "appUser": [], "legacy": false};
const inItem = $input.first();
const wh = inItem.json;
const secrets = [$env.CR_AUTH_SECRET, $env.CR_AUTH_SECRET_PREV];
const compatUntil = Date.parse($env.CR_AUTH_COMPAT_UNTIL || '') || 0;
const nowMs = Date.now();
const token = crAuth.bearer(wh.headers);
let mode = 'session', claims = null, deny = null;
if (!token) {
  if (RULE.legacy && compatUntil > nowMs) mode = 'legacy';
  else deny = 'unauthorized:missing';
} else {
  const v = crAuth.verify(token, secrets, Math.floor(nowMs / 1000));
  if (!v.ok) deny = 'unauthorized:' + v.reason; else claims = v.claims;
}
const body = (wh.body && typeof wh.body === 'object') ? wh.body : {};
const isSentinel = (x) => x === undefined || x === null || x === '' || x === '-1';
const listOf = (v) => (Array.isArray(v) ? v : [v]);
const owned = (set, v) => listOf(v).every((x) => isSentinel(x) || (typeof x === 'string' && set.includes(x)));
if (!deny && mode === 'session') {
  for (const f of RULE.profiles || []) if (!owned(claims.p, body[f])) { deny = 'forbidden:' + f; break; }
  if (!deny) for (const f of RULE.workflows || []) if (!owned(claims.w, body[f])) { deny = 'forbidden:' + f; break; }
  if (!deny) for (const f of RULE.appUser || []) {
    const v = body[f];
    if (isSentinel(v)) {
      if ((RULE.appUserRequired || []).includes(f)) { deny = 'forbidden:' + f; break; }
      continue;
    }
    if (!claims.u || String(v) !== claims.u) { deny = 'forbidden:' + f; break; }
  }
}
return [{ json: { ...wh, crAuth: {
  ok: !deny, mode, reason: deny,
  installId: claims ? claims.i : null, appUserId: claims ? claims.u : null,
  profiles: claims ? claims.p : [], workflows: claims ? claims.w : [], claimPending: claims ? (claims.c || []) : [],
} }, ...(inItem.binary ? { binary: inItem.binary } : {}), pairedItem: { item: 0 } }];

// TEST DIALOG / Validate (generated — build-test-dialog.py). Owner-scoped by the gate; defensive re-check.
const wh = $input.first().json || {};
const b = wh.body || {};
const owned = wh.crAuth || {};
const s = (v, max) => (typeof v === 'string' ? v.trim().slice(0, max) : '');
const profileId = s(b.profileId, 128), workflowId = s(b.workflowId, 64), text = s(b.text, 2000);
const channel = b.channel === 'telegram' ? 'telegram' : 'whatsapp';
if (!profileId || !workflowId || !text) return [{ json: { ok: false, error: 'bad_request' } }];
if (!(owned.profiles || []).includes(profileId) || !(owned.workflows || []).includes(workflowId)) return [{ json: { ok: false, error: 'forbidden' } }];
const history = (Array.isArray(b.history) ? b.history : []).slice(-10)
  .map(m => ({ role: (m && m.role === 'business') ? 'business' : 'client', text: s(m && m.text, 500) })).filter(m => m.text);
return [{ json: { ok: true, profileId, workflowId, channel, text, history, runId: String($execution.id),
                  filterKey: channel === 'telegram' ? 'botTgId' : 'botWaId' } }];

// TEST DIALOG / Compose: the bot's REAL system message (the AI Agent node of its own workflow) + what
// knowledge it carries. Nothing is re-composed from client data — a test that lies about the prompt is worthless.
// WHICH version (R15): n8n 2.x returns the saved DRAFT as `nodes`/`versionId` and the PUBLISHED graph a live webhook runs
// as `activeVersion`/`activeVersionId`. An active bot is tested by its published version (what clients get); an inactive
// one (deactivation clears activeVersion) by its draft — exactly what activation publishes — and the response says so.
// An active bot whose published version is not readable fails closed: never a silent fallback to the draft.
const v = $('Validate').first().json;
const r = $input.first().json || {};
const wf = (r.body && typeof r.body === 'object') ? r.body : r;
const draftId = (typeof wf.versionId === 'string' && wf.versionId) || null;
const activeId = (typeof wf.activeVersionId === 'string' && wf.activeVersionId) || null;
const av = wf.activeVersion;
const published = (av && typeof av === 'object' && Array.isArray(av.nodes) && (!av.versionId || av.versionId === activeId)) ? av.nodes : null;
let nodes;
if (!activeId) nodes = Array.isArray(wf.nodes) ? wf.nodes : [];
else if (published) nodes = published;
else if (activeId === draftId && Array.isArray(wf.nodes)) nodes = wf.nodes;
else return [{ json: { ok: false, error: 'bot_prompt_unavailable', detail: 'published_version_unreadable' } }];
const promptVersion = { source: activeId ? 'published' : 'draft', versionId: activeId || draftId,
                        draftPending: !!(activeId && draftId && draftId !== activeId) };
const agent = nodes.find(n => n && n.name === 'AI Agent');
const sm = agent && agent.parameters && agent.parameters.options ? String(agent.parameters.options.systemMessage || '') : '';
if (!sm) return [{ json: { ok: false, error: 'bot_prompt_unavailable', detail: r.statusCode && r.statusCode !== 200 ? 'http ' + r.statusCode : 'agent_prompt_missing', promptVersion } }];
// the transcript the model sees: the owner's synthetic history + the test message (no memory node — the bot's memory is untouched)
const lines = v.history.map(m => (m.role === 'client' ? 'Клиент: ' : 'Бизнес: ') + m.text);
const text = lines.length ? lines.join('\n') + '\nКлиент: ' + v.text : v.text;
return [{ json: { ok: true, systemMessage: sm, text, promptVersion, sources: {
  catalog: /Product1:|Service1:/.test(sm), contacts: /Контакты:/.test(sm), businessText: /About Business:\s*\S/.test(sm.replace(/About Business:\s*\n\s*Контакты:/, '')) } } }];

// TEST DIALOG / Sources: the price-list fragments this question could draw on (same table, same per-bot scope
// as the bot's own retrieval tool), listed for the owner — never sent to the client.
const docs = [];
for (const it of $input.all()) {
  const j = it && it.json;
  if (!j || j.error) continue;
  const d = j.document || j;
  const content = d && (d.pageContent || d.content);
  if (content) docs.push({ snippet: String(content).slice(0, 160), fileId: (d.metadata || {}).fileId || null });
}
const c = $('Compose').first().json;
return [{ json: { text: c.text, systemMessage: c.systemMessage, sources: { ...c.sources, documents: docs } } }];

// TEST DIALOG / Build Response: the reply, the sources it could use, the action it would have taken, the
// correlation id — and an honest error when the model or the prompt read failed.
const v = $('Validate').first().json;
let reply = '';
try { reply = String($('AI Agent').first().json.output || ''); } catch (e) { reply = ''; }
let sources = {};
try { sources = $('Sources').first().json.sources || {}; } catch (e) { sources = {}; }
let actions = [];
try { actions = $input.first().json.actions || []; } catch (e) { actions = []; }
const handoff = actions.find(a => a.action === 'create_handoff');
let promptVersion = null;   // which version of the bot answered (R15): {source: published|draft, versionId, draftPending}
try { promptVersion = $('Compose').first().json.promptVersion || null; } catch (e) { promptVersion = null; }
if (!reply.trim()) return [{ json: { success: false, error: 'generation_failed', correlationId: v.runId, promptVersion, _status: 200 } }];
return [{ json: { success: true, reply, sources, wouldHandoff: handoff ? (handoff.args || {}) : null,
                  wouldSend: true, sent: false, quotaCounted: false, correlationId: v.runId, promptVersion, _status: 200 } }];
